// Native & Web Universal PDF Export Helper
const downloadPdfDocument = async (html: string, fileName: string) => {
  try {
    if (Platform.OS ==="web") {
      if (typeof window !=="undefined"&& window.document) {
        const printWindow = window.open("","_blank");
        if (printWindow) {
          printWindow.document.write(html);
          printWindow.document.close();
          printWindow.print();
        }
      }
    } else {
      // Native Mobile (Android & iOS)
      // Directly opens the OS Native"Save as PDF / Print"system viewer
      await Print.printAsync({ html });
    }
  } catch (error: any) {
    Alert.alert("PDF Export Error", error.message ||"Failed to generate PDF document.");
  }
};

// Client-side image compression helpers to optimize base64 payloads and prevent network aborts & Firestore 1MB limits
const compressImageBase64 = (dataUrl: string, maxWidth = 600, maxHeight = 600, quality = 0.7): Promise<string> => {
  if (!dataUrl || dataUrl ==="test"|| !dataUrl.startsWith("data:image")) return Promise.resolve(dataUrl);
  if (dataUrl.length < 150000) return Promise.resolve(dataUrl);

  if (typeof window !=="undefined"&& typeof document !=="undefined") {
    return new Promise((resolve) => {
      const img = new (window as any).Image();
      img.onload = () => {
        let width = img.width;
        let height = img.height;
        if (width > maxWidth || height > maxHeight) {
          if (width > height) {
            height = Math.round((height * maxWidth) / width);
            width = maxWidth;
          } else {
            width = Math.round((width * maxHeight) / height);
            height = maxHeight;
          }
        }
        const canvas = document.createElement("canvas");
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext("2d");
        if (ctx) {
          ctx.drawImage(img, 0, 0, width, height);
          resolve(canvas.toDataURL("image/jpeg", quality));
        } else {
          resolve(dataUrl);
        }
      };
      img.onerror = () => resolve(dataUrl);
      img.src = dataUrl;
    });
  }
  return Promise.resolve(dataUrl);
};

const compressFileImage = (file: any, maxWidth = 600, maxHeight = 600, quality = 0.7): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error("Failed to read image file"));
    reader.onload = (e: any) => {
      const dataUrl = e.target.result;
      const img = new (window as any).Image();
      img.onerror = () => resolve(dataUrl);
      img.onload = () => {
        let width = img.width;
        let height = img.height;
        if (width > maxWidth || height > maxHeight) {
          if (width > height) {
            height = Math.round((height * maxWidth) / width);
            width = maxWidth;
          } else {
            width = Math.round((width * maxHeight) / height);
            height = maxHeight;
          }
        }
        const canvas = document.createElement("canvas");
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext("2d");
        if (ctx) {
          ctx.drawImage(img, 0, 0, width, height);
          resolve(canvas.toDataURL("image/jpeg", quality));
        } else {
          resolve(dataUrl);
        }
      };
      img.src = dataUrl;
    };
    reader.readAsDataURL(file);
  });
};

// Safe cross-platform local storage helper for Guest Demo sessions
const guestStorage = {
  async save(email: string) {
    try {
      if (Platform.OS ==="web") {
        localStorage.setItem("nermai_guest_email", email);
        localStorage.setItem("nermai_guest_auto_login","true");
      }
    } catch (e) {
      console.log("Failed to save guest credentials locally:", e);
    }
  },
  async get() {
    try {
      if (Platform.OS ==="web") {
        const email = localStorage.getItem("nermai_guest_email") ||"";
        const autoLogin = localStorage.getItem("nermai_guest_auto_login") ==="true";
        return { email, autoLogin };
      }
    } catch (e) {
      console.log("Failed to load guest credentials:", e);
    }
    return { email:"", autoLogin: false };
  },
  async disableAutoLogin() {
    try {
      if (Platform.OS ==="web") {
        localStorage.setItem("nermai_guest_auto_login","false");
      }
    } catch (e) { }
  },
  async clear() {
    try {
      if (Platform.OS ==="web") {
        localStorage.removeItem("nermai_guest_name");
        localStorage.removeItem("nermai_guest_phone");
        localStorage.removeItem("nermai_guest_email");
      }
    } catch (e) { }
  }
};

const SEVEN_DAYS_MS = 7 * 24 * 60 * 60 * 1000;

// Safe cross-platform local storage helper for authenticated user sessions
const userStorage = {
  async save(userData: any) {
    try {
      if (Platform.OS === "web" && typeof localStorage !== "undefined") {
        const payload = {
          ...userData,
          loginTimestamp: Date.now(),
          sessionExpiry: Date.now() + SEVEN_DAYS_MS
        };
        localStorage.removeItem("nermai_manual_logout");
        localStorage.setItem("nermai_auth_user", JSON.stringify(payload));
      }
    } catch (e) {
      console.log("Failed to save user session locally:", e);
    }
  },
  async get() {
    try {
      if (Platform.OS === "web" && typeof localStorage !== "undefined") {
        const raw = localStorage.getItem("nermai_auth_user");
        if (!raw) return null;
        const parsed = JSON.parse(raw);
        if (parsed.sessionExpiry && Date.now() > parsed.sessionExpiry) {
          localStorage.removeItem("nermai_auth_user");
          return null;
        }
        if (parsed.loginTimestamp && (Date.now() - parsed.loginTimestamp > SEVEN_DAYS_MS)) {
          localStorage.removeItem("nermai_auth_user");
          return null;
        }
        return parsed;
      }
    } catch (e) {
      console.log("Failed to load user session:", e);
    }
    return null;
  },
  async clear() {
    try {
      if (Platform.OS === "web" && typeof localStorage !== "undefined") {
        localStorage.removeItem("nermai_auth_user");
      }
    } catch (e) { }
  }
};

// Web Portal LocalStorage Exam Persistence Helper for high performance and offline resilience
const examLocalStorage = {
  saveDraft(attemptId: string, data: any) {
    try {
      if (Platform.OS ==="web"&& typeof localStorage !=="undefined") {
        localStorage.setItem(`nermai_exam_draft_${attemptId}`, JSON.stringify({ ...data, updatedAt: Date.now() }));
      }
    } catch (e) { }
  },
  getDraft(attemptId: string) {
    try {
      if (Platform.OS ==="web"&& typeof localStorage !=="undefined") {
        const raw = localStorage.getItem(`nermai_exam_draft_${attemptId}`);
        return raw ? JSON.parse(raw) : null;
      }
    } catch (e) { }
    return null;
  },
  clearDraft(attemptId: string) {
    try {
      if (Platform.OS ==="web"&& typeof localStorage !=="undefined") {
        localStorage.removeItem(`nermai_exam_draft_${attemptId}`);
      }
    } catch (e) { }
  }
};

function DateTimePickerSelect({
  value,
  onChange,
  label,
  darkMode
}: {
  value: string;
  onChange: (val: string) => void;
  label: string;
  darkMode: boolean;
}) {
  const [showModal, setShowModal] = useState(false);
  const [activeField, setActiveField] = useState<"year"|"month"|"day"|"hour"|"minute"| null>(null);

  // Parse current value
  let date = new Date();
  if (value) {
    const parsed = new Date(value);
    if (!isNaN(parsed.getTime())) {
      date = parsed;
    }
  }

  const curYear = date.getFullYear();
  const curMonth = date.getMonth() + 1; // 1-12
  const curDay = date.getDate();
  const curHour = date.getHours();
  const curMin = date.getMinutes();

  // Options arrays
  const years = Array.from({ length: 6 }, (_, i) => String(new Date().getFullYear() + i));
  const months = Array.from({ length: 12 }, (_, i) => String(i + 1).padStart(2,"0"));
  const days = Array.from({ length: 31 }, (_, i) => String(i + 1).padStart(2,"0"));
  const hours = Array.from({ length: 24 }, (_, i) => String(i).padStart(2,"0"));
  const minutes = Array.from({ length: 12 }, (_, i) => String(i * 5).padStart(2,"0"));

  const updateParts = (updates: { y?: string; m?: string; d?: string; hr?: string; min?: string }) => {
    const y = updates.y || String(curYear);
    const m = updates.m || String(curMonth).padStart(2,"0");
    const d = updates.d || String(curDay).padStart(2,"0");
    const hr = updates.hr || String(curHour).padStart(2,"0");
    const min = updates.min || String(curMin).padStart(2,"0");
    onChange(`${y}-${m}-${d}T${hr}:${min}`);
  };

  const getActiveOptions = () => {
    if (activeField ==="year") return years;
    if (activeField ==="month") return months;
    if (activeField ==="day") return days;
    if (activeField ==="hour") return hours;
    if (activeField ==="minute") return minutes;
    return [];
  };

  const getActiveTitle = () => {
    if (activeField ==="year") return"Select Year";
    if (activeField ==="month") return"Select Month";
    if (activeField ==="day") return"Select Day";
    if (activeField ==="hour") return"Select Hour";
    if (activeField ==="minute") return"Select Minute";
    return"";
  };

  const handleSelect = (val: string) => {
    if (activeField ==="year") updateParts({ y: val });
    else if (activeField ==="month") updateParts({ m: val });
    else if (activeField ==="day") updateParts({ d: val });
    else if (activeField ==="hour") updateParts({ hr: val });
    else if (activeField ==="minute") updateParts({ min: val });
    setShowModal(false);
    setActiveField(null);
  };

  const openPicker = (field:"year"|"month"|"day"|"hour"|"minute") => {
    setActiveField(field);
    setShowModal(true);
  };

  const monthNames: Record<string, string> = {
    "01":"Jan","02":"Feb","03":"Mar","04":"Apr","05":"May","06":"Jun",
    "07":"Jul","08":"Aug","09":"Sep","10":"Oct","11":"Nov","12":"Dec"
  };

  return (
    <View style={{ marginBottom: 12 }}>
      <Text style={{ fontSize: 12, fontWeight:"bold", color: darkMode ?"#ccc":"#444", marginBottom: 6 }}>{label}</Text>

      <View style={{ flexDirection:"row", gap: 6 }}>
        {/* Day */}
        <TouchableOpacity onPress={() => openPicker("day")} style={{ flex: 1, padding: 10, borderWidth: 1, borderColor: darkMode ?"#444":"#ccc", borderRadius: 8, backgroundColor: darkMode ?"#222":"#fff", alignItems:"center"}}>
          <Text style={{ color: darkMode ?"#fff":"#212121", fontSize: 13, fontWeight:"bold"}}>{String(curDay).padStart(2,"0")}</Text>
          <Text style={{ color:"#888", fontSize: 9, marginTop: 2 }}>Day</Text>
        </TouchableOpacity>

        {/* Month */}
        <TouchableOpacity onPress={() => openPicker("month")} style={{ flex: 1.5, padding: 10, borderWidth: 1, borderColor: darkMode ?"#444":"#ccc", borderRadius: 8, backgroundColor: darkMode ?"#222":"#fff", alignItems:"center"}}>
          <Text style={{ color: darkMode ?"#fff":"#212121", fontSize: 13, fontWeight:"bold"}}>{monthNames[String(curMonth).padStart(2,"0")] || String(curMonth).padStart(2,"0")}</Text>
          <Text style={{ color:"#888", fontSize: 9, marginTop: 2 }}>Month</Text>
        </TouchableOpacity>

        {/* Year */}
        <TouchableOpacity onPress={() => openPicker("year")} style={{ flex: 1.5, padding: 10, borderWidth: 1, borderColor: darkMode ?"#444":"#ccc", borderRadius: 8, backgroundColor: darkMode ?"#222":"#fff", alignItems:"center"}}>
          <Text style={{ color: darkMode ?"#fff":"#212121", fontSize: 13, fontWeight:"bold"}}>{curYear}</Text>
          <Text style={{ color:"#888", fontSize: 9, marginTop: 2 }}>Year</Text>
        </TouchableOpacity>

        {/* Hour */}
        <TouchableOpacity onPress={() => openPicker("hour")} style={{ flex: 1.2, padding: 10, borderWidth: 1, borderColor: darkMode ?"#444":"#ccc", borderRadius: 8, backgroundColor: darkMode ?"#222":"#fff", alignItems:"center"}}>
          <Text style={{ color: darkMode ?"#fff":"#212121", fontSize: 13, fontWeight:"bold"}}>{String(curHour).padStart(2,"0")}</Text>
          <Text style={{ color:"#888", fontSize: 9, marginTop: 2 }}>Hr</Text>
        </TouchableOpacity>

        {/* Colon separator */}
        <View style={{ justifyContent:"center", alignItems:"center"}}>
          <Text style={{ color: darkMode ?"#fff":"#444", fontWeight:"bold", fontSize: 16 }}>:</Text>
        </View>

        {/* Minute */}
        <TouchableOpacity onPress={() => openPicker("minute")} style={{ flex: 1.2, padding: 10, borderWidth: 1, borderColor: darkMode ?"#444":"#ccc", borderRadius: 8, backgroundColor: darkMode ?"#222":"#fff", alignItems:"center"}}>
          <Text style={{ color: darkMode ?"#fff":"#212121", fontSize: 13, fontWeight:"bold"}}>{String(curMin).padStart(2,"0")}</Text>
          <Text style={{ color:"#888", fontSize: 9, marginTop: 2 }}>Min</Text>
        </TouchableOpacity>
      </View>

      {showModal && (
        <Modal visible={true} transparent animationType="fade">
          <View style={{ flex: 1, backgroundColor:"rgba(0,0,0,0.5)", justifyContent:"center", alignItems:"center", padding: 20 }}>
            <View style={{ width:"80%", maxHeight:"60%", backgroundColor: darkMode ?"#1e1e1e":"#ffffff", borderRadius: 14, overflow:"hidden", borderWidth: 1, borderColor: darkMode ?"#333":"#eee"}}>
              <View style={{ padding: 16, borderBottomWidth: 1, borderBottomColor: darkMode ?"#333":"#eee", alignItems:"center", backgroundColor: darkMode ?"#222":"#f9f9f9"}}>
                <Text style={{ fontWeight:"bold", fontSize: 15, color: darkMode ?"#fff":"#212121"}}>{getActiveTitle()}</Text>
              </View>
              <ScrollView>
                {getActiveOptions().map((opt) => (
                  <TouchableOpacity
                    key={opt}
                    onPress={() => handleSelect(opt)}
                    style={{ paddingVertical: 14, paddingHorizontal: 20, borderBottomWidth: 1, borderBottomColor: darkMode ?"#2a2a2a":"#f0f0f0"}}
                  >
                    <Text style={{ fontSize: 15, color: darkMode ?"#fff":"#212121", textAlign:"center"}}>{opt}</Text>
                  </TouchableOpacity>
                ))}
              </ScrollView>
              <TouchableOpacity
                onPress={() => { setShowModal(false); setActiveField(null); }}
                style={{ padding: 14, alignItems:"center", backgroundColor: darkMode ?"#222":"#f9f9f9", borderTopWidth: 1, borderTopColor: darkMode ?"#333":"#eee"}}
              >
                <Text style={{ color:"#c62828", fontWeight:"bold", fontSize: 14 }}>Cancel</Text>
              </TouchableOpacity>
            </View>
          </View>
        </Modal>
      )}
    </View>
  );
}

function PageLockedBanner({ pageTitle, message, darkMode }: { pageTitle: string; message?: string; darkMode: boolean }) {
  return (
    <View style={{ flex: 1, alignItems:"center", justifyContent:"center", padding: 30, backgroundColor: darkMode ?"#121212":"#f8f9fa", minHeight: 450 }}>
      <View style={{
        maxWidth: 480, width:"100%", backgroundColor: darkMode ?"#1e1e1e":"#ffffff",
        borderRadius: 16, padding: 32, alignItems:"center", borderWidth: 1, borderColor: darkMode ?"#2a2a2a":"#ffebee",
        shadowColor:"#000", shadowOpacity: 0.08, shadowRadius: 12, shadowOffset: { width: 0, height: 4 }, elevation: 4
      }}>
        <View style={{ width: 64, height: 64, borderRadius: 32, backgroundColor:"#ffebee", alignItems:"center", justifyContent:"center", marginBottom: 16 }}>
          <Ionicons name="lock-closed"size={32} color="#c62828"/>
        </View>
        <Text style={{ fontSize: 20, fontWeight:"800", color: darkMode ?"#ef9a9a":"#c62828", marginBottom: 6, textAlign:"center"}}>
          {pageTitle} Under Maintenance
        </Text>
        <Text style={{ fontSize: 13, color: darkMode ?"#b0bec5":"#616161", textAlign:"center", lineHeight: 20, marginBottom: 20 }}>
          {message ||"This section is currently undergoing scheduled maintenance or system updates. Access has been temporarily restricted by the system administrator."}
        </Text>
        <View style={{ width:"100%", backgroundColor: darkMode ?"#2a2a2a":"#fff8f8", borderRadius: 10, padding: 14, borderWidth: 1, borderColor: darkMode ?"#3a3a3a":"#ffcdd2", alignItems:"center"}}>
          <Text style={{ fontSize: 11, color:"#c62828", fontWeight:"bold"}}>Notice from NERMAI Administration</Text>
          <Text style={{ fontSize: 11, color: darkMode ?"#9e9e9e":"#757575", marginTop: 4, textAlign:"center"}}>
            Please check back shortly or contact the office administration if you require immediate assistance.
          </Text>
        </View>
      </View>
    </View>
  );
}

