  const getFeatureAccess = (featureKey: string): "none" | "view" | "edit_direct" | "edit_on_approval" => {
    if (!user) return "none";
    if (user.role === "developer" || user.role === "super_admin") return "edit_direct";
    const rawCustom = user.customPermissions?.[featureKey];
    if (rawCustom) {
      if (rawCustom === "none") return "none";
      if (rawCustom === "view" || rawCustom === "CRU only" || rawCustom === "CR only" || rawCustom === "U only") return "view";
      if (rawCustom === "edit_direct" || rawCustom === "CRUD") return "edit_direct";
      return "edit_on_approval";
    }
    const rawRole = rolePermissions?.[user.role]?.[featureKey];
    if (rawRole) {
      if (rawRole === "none") return "none";
      if (rawRole === "view" || rawRole === "CRU only" || rawRole === "CR only" || rawRole === "U only") return "view";
      if (rawRole === "edit_direct" || rawRole === "CRUD") return "edit_direct";
      return "edit_on_approval";
    }
    return "edit_on_approval";
  };

  const executeEditOrApproval = (
    featureKey: string,
    actionType: "create" | "edit" | "delete",
    proposedPayload: any,
    directCallback: () => Promise<void> | void,
    targetCollection?: string,
    docId?: string
  ) => {
    const access = getFeatureAccess(featureKey);
    if (access === "none") {
      Alert.alert("Permission Denied", "You do not have permission to perform actions in this section.");
      return;
    }
    if (access === "view") {
      Alert.alert("Read-Only Access", "Your admin permissions for this feature are set to View Only.");
      return;
    }
    if (access === "edit_direct") {
      directCallback();
      return;
    }
    if (access === "edit_on_approval") {
      confirmAction(
        "Super Admin Approval Required",
        `Your admin account requires Super Admin approval to ${actionType} items in this section. Submit proposal for Super Admin review?`,
        async () => {
          try {
            await api.post("/developer/collection/notifications", {
              type: actionType === "delete" ? "delete_approval" : actionType === "create" ? "create_approval" : "edit_approval",
              feature: featureKey,
              targetCollection: targetCollection || featureKey,
              docId: docId || proposedPayload?.id || proposedPayload?._id || "new_document",
              proposedPayload,
              requestedBy: user?.name || user?.username || "Admin",
              status: "pending",
              createdAt: new Date().toISOString()
            });
            Alert.alert("Submitted for Approval", "Your change proposal has been submitted to Super Admin for review.");
          } catch (e: any) {
            Alert.alert("Error", e.message || "Failed to submit request.");
          }
        },
        "Submit Request",
        false
      );
    }
  };

  // Legacy Permissions Helpers
  const getPermission = (feature: string): string => {
    if (user?.role === "developer") return "CRUD";
    if (!rolePermissions || !user?.role) return "CRUD"; // Default fallback
    const roleKey = user.role;
    return rolePermissions[roleKey]?.[feature] || "CRUD";
  };

  const hasPermission = (feature: string, action: "C" | "R" | "U" | "D"): boolean => {
    if (user?.role === "developer" || user?.role === "super_admin") return true;
    const perm = getPermission(feature);
    if (action === "C") return perm.includes("C");
    if (action === "R") return perm.includes("R");
    if (action === "U") return perm.includes("U");
    if (action === "D") {
      return perm.includes("D") || perm === "Delete but approval required from super admin";
    }
    return false;
  };

